mapper.select:
SELECT
    e.ERROR_ID       AS errorId,
    e.APPLICATION_ID AS applicationId,
    a.APPLICATION_NO AS applicationNo,
    a.CUSTOMER_ID    AS customerId,
    e.FAILED_STEP    AS failedStep,
    e.ERROR_CODE     AS errorCode,
    e.ERROR_MESSAGE  AS errorMessage,
    e.STATUS         AS status,
    e.RETRY_COUNT    AS retryCount,
    e.CREATED_AT     AS createdAt
FROM TB_REFINANCE_ERROR e
JOIN TB_REFINANCE_APPLICATION a ON a.APPLICATION_ID = e.APPLICATION_ID


        AND CAST(e.CREATED_AT AS DATE) = #{transactionDate}


        AND a.APPLICATION_NO = #{applicationNo}


        AND a.CUSTOMER_ID = #{customerId}


        AND e.FAILED_STEP = #{failedStep}


        AND e.ERROR_CODE = #{errorCode}


        AND e.STATUS = #{status}


ORDER BY e.CREATED_AT DESC
